#!/usr/bin/env bash
# Generates the Jack-o'-Lantern woods assets + the catoblepas via the direct
# image CLI (1024x1024 PNGs) into /tmp/gen_<name>.png.
set -u
G=/google/bin/releases/gemini-agents-generate/generate
STYLE='32-bit era (mid-1990s console) 2D pixel art for a gothic horror side-scrolling action platformer. Crisp hard-edged pixel clusters, limited palette, flat shading with 2-3 tones per material, no anti-aliasing blur, no painterly or photoreal rendering. Strict side view, orthographic. No text, no labels, no watermark, no signature, no frame borders.'
KEY='The background must be one flat solid pure bright green (#00FF00) with no gradient, no ground shadows, and nothing touching the image edges. Nothing green anywhere on the subjects.'
gen() {
  local name="$1"; shift
  if [ -s "/tmp/gen_${name}.png" ]; then echo "= ${name} exists"; return; fi
  for attempt in 1 2 3; do
    "$G" -prod -timeout=180s -output="/tmp/gen_${name}.png" image -model=gempix-2-flash-lite-png "$STYLE $*" 2>&1 | grep -E "Successfully|rror|denied|capacity" | tail -1
    [ -s "/tmp/gen_${name}.png" ] && break
    sleep 15
  done
}
gen catoblepas "Palette: dark umber and slate-grey hide, deep indigo shadows, bone ivory horns and hooves, dull violet-grey breath, glowing red eyes. SPRITE SHEET of ONE catoblepas enemy facing RIGHT in every frame: a heavy stooped buffalo-like beast with a dark scaly hide along its back, thick legs with ivory hooves, a long drooping neck and a huge boar-like head hanging very low near the ground, short curved ivory horns, small glowing red eyes and a stiff bristled mane. Layout: a 2 by 2 grid of cells with wide even green gaps, all at the same scale with hooves on a shared baseline per row: top-left front legs forward (walk 1), top-right legs passing (walk 2), bottom-left rear legs forward (walk 3), bottom-right head lifted slightly with jaws open exhaling a billowing cloud of dull violet-grey petrifying breath toward the right. $KEY"
gen pumpkin "Palette: bright orange pumpkin skin with darker orange ribs, brown stems, glowing amber-yellow carved faces, dark indigo shadows, warm fire tones. SPRITE SHEET of jack-o-lantern enemies facing RIGHT, a 2 by 2 grid of cells with wide even green gaps, all at the same scale: top-left a squat carved pumpkin crouched low on short root-like brown vine legs (ready to hop), top-right the same pumpkin mid-hop with vine legs tucked and a wicked grin, bottom-left a carved pumpkin head floating with a crown of amber flames licking upward (flame frame 1), bottom-right the same floating flaming pumpkin head with the flames bent to the left as if rushing forward (flame frame 2). Carved triangular eyes and a jagged grin glowing from inside. $KEY"
gen dragon "Palette: dark crimson and black scales, charcoal wing membranes with bone-ivory claws, amber-orange fire, glowing yellow eyes, deep indigo shadows. SPRITE SHEET of ONE lean wyvern-like dragon enemy facing RIGHT, a 2 by 2 grid of cells with wide even green gaps, all at the same scale: top-left flying with wings raised high, top-right flying with wings swept low, bottom-left gliding with wings level and neck stretched forward, bottom-right hovering with jaws open breathing a short jet of amber fire toward the right. Long tail with a spade tip, horned head, no rider. $KEY"
gen forestfloor "Palette: russet, rust-orange and brown fallen autumn leaves, dark umber earth, deep indigo shadows, bone ivory, pale grey stones. SIDE-VIEW TERRAIN CROSS-SECTION STRIP of a haunted autumn forest floor, horizontally seamless (the left edge continues the right edge). The top 25 percent of the image is flat solid pure bright green (#00FF00) with nothing in it. At exactly 25 percent from the top is a perfectly horizontal ground surface covered in a thin layer of russet and rust-orange fallen leaves with a few small brown mushrooms and twigs poking slightly up into the green. Below the surface the remaining 75 percent is packed dark umber earth with thick gnarled tree roots, embedded grey stones and a buried skull, getting darker toward the bottom edge. No objects above the surface except the small mushrooms and twigs, no text."
gen deepforest "Palette: near-black umber trunks, dark brown and rust-orange autumn canopy, deep indigo shadows, glowing amber-orange carved pumpkin faces. MID-DISTANCE PARALLAX BACKGROUND LAYER of a haunted autumn forest: a continuous row of enormous gnarled bare and half-bare trees with twisted trunks and reaching branches, drawn as dark umber silhouettes with rust-orange rim highlights on the upper-left edges; carved jack-o-lanterns glowing amber sit on the roots, hang from branches on ropes and are stacked in small piles between the trunks; a solid dark ground fill across the bottom 12 percent so the bottom edge is completely filled. The layer must be horizontally seamless (the left edge continues the right edge), and the composition must fit within the middle horizontal band of the image (the top 20 percent and bottom 5 percent may be empty). Everything above the trees must be one flat solid pure bright green (#00FF00) with no gradient, no stars, no moon, no fog. Nothing green anywhere on the trees, leaves or pumpkins."
gen pumpkinprops "Palette: bright orange pumpkin skin, brown stems, glowing amber carved faces, dark umber wood, straw yellow, deep indigo shadows. A ROW of 5 separate props for a haunted autumn forest platformer, in one horizontal row with wide even green gaps, strict side view, same scale, all standing on the same invisible baseline: (1) a large carved jack-o-lantern glowing amber with a wicked grin, (2) a small carved jack-o-lantern with a surprised face, (3) a pile of three uncarved pumpkins, (4) a ragged scarecrow on a wooden cross with a carved pumpkin head and a tattered black coat, (5) a dead hollow tree stump with a few bare roots. $KEY"
ls -la /tmp/gen_*.png
